#include <stdio.h>
#include <string.h>

#define MAXS 205

int S, T, P;
int h[MAXS];
int adj[MAXS][MAXS];
int deg[MAXS];
int memo[MAXS];

int dfs(int v) {
    if (memo[v] != -1) return memo[v];

    int best = 0;
    for (int i = 0; i < deg[v]; i++) {
        int u = adj[v][i];
        if (h[v] > h[u]) {
            int cur = 1 + dfs(u);
            if (cur > best) best = cur;
        }
    }

    memo[v] = best;
    return best;
}

int main() {
    if (scanf("%d %d %d", &S, &T, &P) != 3) return 0;

    for (int i = 1; i <= S; i++) {
        scanf("%d", &h[i]);
    }

    for (int i = 0; i < T; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        adj[a][deg[a]++] = b;
        adj[b][deg[b]++] = a;
    }

    memset(memo, -1, sizeof(memo));
    printf("%d\n", dfs(P));

    return 0;
}
